mapper.update:
UPDATE flow_node
SET node_code = #{nodeCode}, node_name = #{nodeName}, node_type = #{nodeType},
    sort_order = #{sortOrder}, config = #{config}, example_output = #{exampleOutput}, branch_of = #{branchOf}
WHERE id = #{id}

mapper.select:
SELECT * FROM flow_node
WHERE node_type = #{nodeType}
  AND JSON_UNQUOTE(JSON_EXTRACT(config, CONCAT('$.', #{jsonKey}))) = #{refId}
